 41 | const SOLE = 640;                 // sole height below head-center anchor (local u)
 42 | const WALK_PERIOD = 0.72;         // s per walk cycle
 43 | const WALK_STANCE = 0.55;         // stance fraction of the cycle
 44 | const WALK_AMP = 46;              // footAt swing amplitude (local u)
 45 | const WALK_LOCAL_SPEED = (2 * WALK_AMP) / (WALK_STANCE * WALK_PERIOD); // 232.32 u/s
 46 | 
 47 | const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
 48 | const lerp = (a, b, k) => a + (b - a) * k;
 49 | const sstep = k => { k = clamp(k, 0, 1); return k * k * (3 - 2 * k); };
