254 | function checkerFloor() {
255 |   // perspective checker on the floor trapezoid: rows bunch toward the wall,
256 |   // columns ease outward toward the camera (same family as environment.mjs)
257 |   const topL = 60, topR = 1020, botL = 0, botR = 1080, yTop = 1300, yBot = 1920;
258 |   const edge = y => {
259 |     const t = clamp((y - yTop) / (yBot - yTop));
260 |     return [topL + (botL - topL) * t, topR + (botR - topR) * t];
261 |   };
262 |   const ROWS = 10, COLS = 10;
263 |   const rows = [];
264 |   for (let i = 0; i <= ROWS; i++) {
265 |     const p = i / ROWS, y = yTop + (yBot - yTop) * Math.pow(p, 1.55);
266 |     rows.push({ y, e: edge(y) });
267 |   }
268 |   const colX = (j, e) => e[0] + (e[1] - e[0]) * (j / COLS);
269 |   let s = path(`M${topL} ${yTop} L${topR} ${yTop} L${botR} ${yBot} L${botL} ${yBot} Z`, 'url(#re-floorBase)');
270 |   for (let i = 0; i < ROWS; i++) {
271 |     for (let j = 0; j < COLS; j++) {
272 |       const a = rows[i], b = rows[i + 1];
273 |       s += path(`M${n(colX(j, a.e))} ${n(a.y)} L${n(colX(j + 1, a.e))} ${n(a.y)} L${n(colX(j + 1, b.e))} ${n(b.y)} L${n(colX(j, b.e))} ${n(b.y)} Z`,
274 |         (i + j) % 2 ? '#332c3a' : '#262030');
275 |     }
276 |   }
277 |   // grout
278 |   s += `<g stroke="#0a0712" stroke-width="1.1" opacity=".5" fill="none">`;
279 |   for (let i = 0; i <= ROWS; i++) {
280 |     const r = rows[i];
281 |     s += `M${n(r.e[0])} ${n(r.y)} L${n(r.e[1])} ${n(r.y)}`;
282 |   }
283 |   for (let j = 0; j <= COLS; j++) {
284 |     s += `M${n(colX(j, rows[0].e))} ${yTop} L${n(colX(j, rows[ROWS].e))} ${yBot}`;
285 |   }
286 |   s += '</g>';
287 |   // light on the floor: warm lamp pool right, cyan spill left, pink kiss far right
288 |   s += `<ellipse cx="838" cy="1560" rx="400" ry="180" fill="url(#re-lampPool)"/>`;
289 |   s += `<ellipse cx="838" cy="1330" rx="300" ry="80" fill="url(#re-lampPool)" opacity=".7"/>`;
290 |   s += rect(0, 1300, 560, 620, 'url(#re-cyanWash)', 'opacity=".6"');
291 |   s += rect(700, 1300, 380, 620, 'url(#re-pinkWash)', 'opacity=".7"');
292 |   // baseboard shadow where wall meets floor
293 |   s += rect(60, 1288, 960, 14, '#120d12', 'opacity=".7"');
294 |   return s;
295 | }
