  1 | // washer-row.mjs — full-frame insert shot "washer-row" (14.47–17.25 s,
  2 | // captions "…ใส่ผ้า / แล้วรอให้เครื่องซักเสร็จ"): four commercial front-load
  3 | // washers in ONE straight parallel row, frontal, identical size, identical
  4 | // bottom line, equal clear gaps, each with its own floor contact shadow.
  5 | // Reuses drawWasher() from ../../washers.mjs with side:'none', depth:0 —
  6 | // a pure frontal cabinet (no depth planes, no built-in shadow; shadows are
  7 | // painted here so every unit gets an identical one). Room, light and camera
  8 | // are original code in the Snowy Neon palette; fully deterministic in
  9 | // { seconds, progress } — no random, no wall clock, no mutable state.
 10 | //
 11 | // API (see .agent-runs/snowy-neon-noon-revision/specs/03-washer-row.md):
 12 | //   WASHER_ROW_LAYOUT — frozen [{ i, progress, x, y, w, h }]: final
 13 | //     1080x1920 screen-space bounding box of each cabinet's front outline
 14 | //     (local x 1..174, y 3..248 of the washers.mjs front face), eight
 15 | //     entries: i=1..4 at progress 0, then i=1..4 at progress 1.
 16 | //   drawWasherRowShot(ctx, { seconds, progress, width = 1080, height = 1920 })
 17 | //     ctx is a 2D context already sized width×height with identity transform;
 18 | //     paints an opaque full frame that replaces the picture for this shot.
 19 | 
 20 | import { drawWasher } from '../../washers.mjs';
 21 | 
 22 | const FW = 174, FH = 252;          // washer front local units (washers.mjs)
 23 | const OUT_X0 = 1, OUT_X1 = 174;    // front outline x extent (local units)
 24 | const OUT_Y0 = 3, OUT_Y1 = 248;    // front outline y extent (local units)
 25 | 
 26 | const SCALE = 2.0;                 // uniform washer scale
 27 | const W_SCALE = 0.68;              // front width squash (commercial fronts)
 28 | const SX = SCALE * W_SCALE;        // 1.36 px per local x unit
 29 | const GAP = 24;                    // equal clear gap, >= 12 px
 30 | const STEP = FW * SX + GAP;        // cabinet pitch (front width + gap)
 31 | const BOTTOM = 1720;               // shared floor-contact line (world y)
 32 | const ROW_W = 4 * FW * SX + 3 * GAP;
 33 | const X0 = (1080 - ROW_W) / 2;     // left edge of the first cabinet
 34 | 
 35 | const WALL_Y = 1200;               // back wall / floor junction
 36 | const FLOOR_FRONT_Y = 2020;        // floor trapezoid front edge (overscan)
 37 | 
 38 | // Per-unit drum states: spin / tumble / drift / one off, each deterministic
 39 | // from `seconds` via drawWasher's time argument. `total` is the remaining
 40 | // wash time in seconds, counted down on the front display.
 41 | const UNITS = [
 42 |   { i: 1, drumPhase: 'spin',   on: true,  suds: true,  whiteSheet: false, accent: '#4fdcff', phase: 0,   total: 842 },
 43 |   { i: 2, drumPhase: 'tumble', on: true,  suds: false, whiteSheet: true,  accent: '#ff9a2e', phase: 150, total: 517 },
 44 |   { i: 3, drumPhase: 'drift',  on: true,  suds: true,  whiteSheet: false, accent: '#ff4fa8', phase: 300, total: 266 },
 45 |   { i: 4, drumPhase: 'idle',   on: false, suds: false, whiteSheet: false, accent: '#3dff9a', phase: 0,   total: 0 },
 46 | ];
 47 | 
 48 | const clamp01 = v => Math.max(0, Math.min(1, Number.isFinite(v) ? v : 0));
 49 | const ease = p => p * p * (3 - 2 * p);
 50 | const lerp = (a, b, p) => a + (b - a) * p;
 51 | 
 52 | // Gentle lateral track only (<= 40 px over the shot) and <= 3 % scale
 53 | // change about frame centre. No zoom push.
 54 | function camera(progress) {
 55 |   const p = ease(clamp01(progress));
 56 |   return { dx: lerp(-16, 14, p), z: 1 + 0.02 * p };
 57 | }
 58 | 
 59 | function unitX(k) { return X0 + k * STEP; }
 60 | 
 61 | // Front-outline bounding box in world (1080x1920 design) coords.
 62 | function worldBox(k) {
 63 |   return {
 64 |     x: unitX(k) + OUT_X0 * SX,
 65 |     y: BOTTOM - FH * SCALE + OUT_Y0 * SCALE,
 66 |     w: (OUT_X1 - OUT_X0) * SX,
 67 |     h: (OUT_Y1 - OUT_Y0) * SCALE,
 68 |   };
 69 | }
 70 | 
 71 | function screenBox(k, cam) {
 72 |   const b = worldBox(k);
 73 |   return {
 74 |     x: (b.x - 540) * cam.z + 540 + cam.dx,
 75 |     y: (b.y - 960) * cam.z + 960,
 76 |     w: b.w * cam.z,
 77 |     h: b.h * cam.z,
 78 |   };
 79 | }
 80 | 
 81 | const LAYOUT = [];
 82 | for (const p of [0, 1]) {
 83 |   const cam = camera(p);
 84 |   for (let k = 0; k < UNITS.length; k++) {
 85 |     LAYOUT.push(Object.freeze({ i: UNITS[k].i, progress: p, ...screenBox(k, cam) }));
 86 |   }
 87 | }
 88 | export const WASHER_ROW_LAYOUT = Object.freeze(LAYOUT);
 89 | 
 90 | function clock(sec) {
 91 |   const s = Math.max(0, Math.floor(sec));
 92 |   return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
 93 | }
