 97 | function drawWall(g, seconds) {
 98 |   // Warm plaster, darker toward the ceiling; cool night kept in the shadows.
 99 |   const plaster = g.createLinearGradient(0, -120, 0, WALL_Y);
100 |   plaster.addColorStop(0, '#1e1730');
101 |   plaster.addColorStop(0.45, '#3a2a20');
102 |   plaster.addColorStop(1, '#2c2016');
103 |   g.fillStyle = plaster;
104 |   g.fillRect(-120, -120, 1320, WALL_Y + 120);
105 |   // Faint vertical board seams.
106 |   g.strokeStyle = 'rgba(0,0,0,0.10)';
107 |   g.lineWidth = 1;
108 |   for (let x = 60; x < 1080; x += 150) {
109 |     g.beginPath(); g.moveTo(x, 0); g.lineTo(x + 8, WALL_Y); g.stroke();
