 60 | function buildClothSprite() {
 61 |   const c = document.createElement('canvas');
 62 |   c.width = 160; c.height = 320;
 63 |   const g = c.getContext('2d');
 64 |   // Cool ambient base for the dark rear void, lit only by spilled shop
 65 |   // light. No warm key, no facial features anywhere; the top stays a
 66 |   // touch lighter where spill reaches down and the hem falls away darker.
 67 |   const base = g.createLinearGradient(0, 0, 0, 300);
 68 |   base.addColorStop(0, '#d0d9e8');
 69 |   base.addColorStop(0.5, '#b7c0d2');
 70 |   base.addColorStop(1, '#7f8aa0');
 71 |   clothPath(g); g.fillStyle = base; g.fill();
 72 | 
 73 |   g.save(); clothPath(g); g.clip();
 74 |   // Warm spill from the counter's gooseneck lamp (world ~700,1044, just off
 75 |   // the sprite's right edge at mid height): a muted pool warming the
 76 |   // upper-right contour, crown and shoulders, falling off toward the void
 77 |   // side and the hem. Translucent enough that the cloth stays cloth.
 78 |   const lampWash = g.createRadialGradient(176, 132, 10, 176, 132, 195);
 79 |   lampWash.addColorStop(0, 'rgba(255,198,122,0.30)');
 80 |   lampWash.addColorStop(0.5, 'rgba(255,188,116,0.13)');
 81 |   lampWash.addColorStop(1, 'rgba(255,188,116,0)');
 82 |   g.fillStyle = lampWash; g.fillRect(0, 0, c.width, c.height);
 83 |   // Cool fill and shadow from the rear void: a deep slate pool gathering
 84 |   // at the lower left where no lamp reaches, keeping the hem grounded.
 85 |   const voidShade = g.createLinearGradient(36, 110, 30, 315);
 86 |   voidShade.addColorStop(0, 'rgba(50,64,100,0)');
 87 |   voidShade.addColorStop(1, 'rgba(50,64,100,0.30)');
 88 |   g.fillStyle = voidShade; g.fillRect(24, 100, 112, 215);
 89 |   // One broad pale central fold panel flanked by cooler slate side
 90 |   // planes, echoing the original Nun-era drape's folded-cloth values.
 91 |   // Boundaries curve with the crown/shoulder/body instead of running
 92 |   // straight across the torso; the panel leans slightly toward the lamp.
 93 |   const panel = g.createLinearGradient(54, 0, 120, 0);
 94 |   panel.addColorStop(0, 'rgba(228,235,246,0)');
 95 |   panel.addColorStop(0.5, 'rgba(228,235,246,0.36)');
 96 |   panel.addColorStop(1, 'rgba(228,235,246,0)');
 97 |   g.fillStyle = panel; g.fillRect(36, 0, 92, 310);
 98 |   // Slate side planes: soft-edged cool shading hugging both contours. The
 99 |   // void-side (left) plane stays deep; the lamp-side (right) plane is
100 |   // pulled back so the warm wash reads through.
101 |   for (const [fx, a] of [[30, 0.40], [130, 0.20]]) {
102 |     const fg = g.createLinearGradient(fx - 16, 0, fx + 16, 0);
103 |     fg.addColorStop(0, 'rgba(56,70,102,0)');
104 |     fg.addColorStop(0.5, `rgba(56,70,102,${a})`);
105 |     fg.addColorStop(1, 'rgba(56,70,102,0)');
106 |     g.fillStyle = fg; g.fillRect(fx - 16, 0, 32, 310);
107 |   }
108 |   // Soft shade under the covered head/shoulder mass, curved with the
109 |   // shoulder line rather than a horizontal band; its lit crown catches a
110 |   // hint of the lamp's warmth.
111 |   const shoulder = g.createRadialGradient(80, 60, 8, 80, 60, 90);
112 |   shoulder.addColorStop(0, 'rgba(255,236,204,0.16)');
113 |   shoulder.addColorStop(0.55, 'rgba(120,140,175,0.10)');
114 |   shoulder.addColorStop(1, 'rgba(60,74,104,0)');
115 |   g.fillStyle = shoulder; g.fillRect(30, 16, 100, 120);
116 |   const under = g.createLinearGradient(0, 40, 0, 150);
117 |   under.addColorStop(0, 'rgba(70,86,120,0.20)');
118 |   under.addColorStop(1, 'rgba(70,86,120,0)');
119 |   g.fillStyle = under;
120 |   g.beginPath();
121 |   g.moveTo(50, 46); g.bezierCurveTo(58, 90, 56, 130, 54, 160);
122 |   g.lineTo(106, 160); g.bezierCurveTo(104, 130, 102, 90, 110, 46);
123 |   g.closePath(); g.fill();
124 |   // Long fold boundaries curving from under the crown down the A-line
125 |   // body, each a shallow S rather than a straight vertical.
126 |   const folds = [
127 |     [44, 88, 36, 150, 44, 230, 38, 292, 0.24, 3.2],
128 |     [58, 80, 54, 160, 60, 240, 54, 296, 0.15, 2.6],
129 |     [102, 80, 106, 160, 100, 240, 106, 296, 0.16, 2.6],
130 |     [116, 88, 124, 150, 116, 230, 122, 292, 0.22, 3.2],
131 |     [80, 96, 78, 170, 82, 250, 80, 294, 0.10, 2],
132 |   ];
133 |   for (const [x0, y0, c1x, c1y, c2x, c2y, x1, y1, a, w] of folds) {
134 |     g.strokeStyle = `rgba(74,90,124,${a})`; g.lineWidth = w; g.lineCap = 'round';
135 |     g.beginPath(); g.moveTo(x0, y0);
136 |     g.bezierCurveTo(c1x, c1y, c2x, c2y, x1, y1); g.stroke();
137 |   }
138 |   // Contact shadow where the hem meets the floor of the rear void,
139 |   // deepened so the drape reads as grounded rather than floating.
140 |   const hem = g.createLinearGradient(0, 250, 0, 312);
141 |   hem.addColorStop(0, 'rgba(34,42,64,0)');
142 |   hem.addColorStop(1, 'rgba(34,42,64,0.50)');
143 |   g.fillStyle = hem; g.fillRect(28, 246, 104, 66);
144 |   // Restrained cool/warm spill rims from the glazing and counter neon,
145 |   // kept faint so they read as spill, not emitted light.
146 |   g.strokeStyle = 'rgba(79,220,255,0.10)'; g.lineWidth = 2.5; g.lineCap = 'round';
147 |   g.beginPath(); g.moveTo(54, 36); g.bezierCurveTo(46, 96, 45, 190, 40, 288); g.stroke();
148 |   g.strokeStyle = 'rgba(255,79,168,0.08)';
149 |   g.beginPath(); g.moveTo(106, 36); g.bezierCurveTo(114, 96, 115, 190, 120, 288); g.stroke();
150 |   g.restore();
151 |   return c;
152 | }
