154 | function clothMotion(t) {
155 |   // Calm sway early; from ~6.1 s a lateral drift carries the drape behind
156 |   // the right jamb (opening edge x595), gone by ~7.25 s.
157 |   const sway = 4 * Math.sin(t * 0.9) * (1 - sstep((t - 5.6) / 1.2));
158 |   const drift = 118 * sstep((t - 6.1) / 1.15);
159 |   const rock = 1.4 * Math.sin(t * 0.7) * (1 - sstep((t - 5.8) / 1.0));
160 |   return { sway, drift, rock };
161 | }
162 | 
163 | // Draws the cloth in world coordinates. opts.clip === false skips the
164 | // doorway clip — used only by the isolated character-proof page; the
165 | // production path always keeps the clip so jamb/frame are never covered.
166 | export function drawCloth(ctx, t, opts = {}) {
167 |   if (!clothSprite) clothSprite = buildClothSprite();
168 |   const m = clothMotion(t);
169 |   // Pivot near the hem line: sprite pixel (80,295) lands on world
170 |   // (535+sway+drift, 1170), putting the covered head top near world
171 |   // y877 and the irregular hem (local ~y285-299) at world ~y1160-1174,
172 |   // clear of the doorway clip bottom at y1184.
173 |   const px = 535 + m.sway + m.drift, py = 1170;
174 |   ctx.save();
175 |   if (opts.clip !== false) {
176 |     // Clip strictly inside the rear opening so the jamb/frame is never
177 |     // overpainted; the lateral drift exits through the right clip edge.
178 |     ctx.beginPath();
179 |     ctx.rect(471, 776, 123, 408); // x471..594, y776..1184
180 |     ctx.clip();
181 |   }
182 |   // Faint ground contact shadow under the hem, no levitating glow.
183 |   ctx.fillStyle = 'rgba(8,12,24,0.26)';
184 |   ctx.beginPath(); ctx.ellipse(px, 1176, 56, 6, 0, 0, Math.PI * 2); ctx.fill();
185 |   ctx.translate(px, py);
186 |   ctx.rotate(m.rock * Math.PI / 180);
187 |   ctx.translate(-80, -295);
188 |   ctx.drawImage(clothSprite, 0, 0);
189 |   ctx.restore();
190 | }
