192 | // ----------------------------------------------------------- character (SVG)
193 | // Registry-driven character markup. The default model is the registry's
194 | // DEFAULT_MODEL ('cel', the approved pale/slim cel woman); main.mjs selects
195 | // the model from ?model= and forwards it through options.model. World
196 | // placement is fixed here: head center (690,925) at scale 0.5, which puts
197 | // the count-pose tray (local y352) at world ~y1101 and the soles far below
198 | // the counter (clipped at y1110 by the SVG overlay in main.mjs). The uid
199 | // namespaces gradient/clip ids so repeated renders in one frame never
200 | // collide.
201 | export function characterMarkup(t, options = {}) {
202 |   return renderCharacter(t, {
203 |     model: DEFAULT_MODEL, x: 690, y: 925, scale: 0.5, pose: 'count', uid: 'snowy',
204 |     ...options,
205 |   });
206 | }
207 | 
208 | // Deprecated name kept for older callers (character-proof pages, variants):
209 | // despite the name it renders the registry DEFAULT model — currently 'cel',
210 | // not the Nun rig. Use characterMarkup() with an explicit model instead.
211 | export function originalNunMarkup(t, uid = 'snowy') {
212 |   return characterMarkup(t, { uid });
213 | }
