215 | // ------------------------------------------------------------------ entry
216 | export function drawCharacters(ctx, t, shot) {
217 |   t = Number(t) || 0;
218 |   drawCloth(ctx, t);
219 | 
220 |   // Faint cool spill across the doorway, fading once the drape is gone.
221 |   const m = clothMotion(t);
222 |   const visible = 1 - sstep((t - 7.0) / 0.3);
223 |   if (visible > 0.01) {
224 |     ctx.save();
225 |     ctx.beginPath(); ctx.rect(471, 776, 123, 408); ctx.clip();
226 |     const cx = 535 + m.sway + m.drift;
227 |     const spill = ctx.createLinearGradient(cx - 60, 0, cx + 60, 0);
228 |     spill.addColorStop(0, `rgba(79,220,255,${0.05 * visible})`);
229 |     spill.addColorStop(0.5, 'rgba(79,220,255,0)');
230 |     spill.addColorStop(1, `rgba(255,79,168,${0.045 * visible})`);
231 |     ctx.fillStyle = spill;
232 |     ctx.fillRect(465, 770, 140, 420);
233 |     ctx.restore();
234 |   }
235 |   // The character herself is NOT drawn here: main.mjs stamps
236 |   // characterMarkup() into the SVG overlay so Canvas and SVG share one
237 |   // camera matrix.
238 | }
